            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1  # Start or end not found

    queue = deque([(start, 0, 0)])  # (current position, number of steps, number of breaks)
    visited = set()

    while queue:
        current, steps, breaks = queue.popleft()

        if current == end:
            return steps

        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] != '#':
                    if (nx, ny, breaks) not in visited:
                        visited.add((nx, ny, breaks))
                        if grid[nx][ny] == '.':
                            queue.append(((nx, ny), steps + 1, breaks))
                        else:
                            queue.append(((nx, ny), steps + 1, breaks + 1))

    return -1  # No valid path found
```

