from typing import List

def pascal_row(n: int) -> List[int]:
    if n == 0:
        return [1]

    prev_row = pascal_row(n - 1)
    current_row = [1]

    for i in range(1, n):
        current_row.append(prev_row[i - 1] + prev_row[i])

    current_row.append(1)

    return current_row

