def decimal_to_binary(n: int) -> str:
    if n == 0:
        return '0'

    is_negative = n < 0
    n = abs(n)

    binary_digits = []
    while n > 0:
        binary_digits.append(str(n % 2))
        n //= 2

    if is_negative:
        # Convert to two's complement for negative numbers
        binary_digits.reverse()
        carry = 1
        for i in range(len(binary_digits)):
            if binary_digits[i] == '1':
                binary_digits[i] = '0'
            else:
                binary_digits[i] = '1'
                break
            carry = 0
        if carry:
            binary_digits.append('1')

    binary_digits.reverse()
    return ''.join(binary_digits)
