def run_length_encode(s: str) -> list[tuple[str, int]]:
    if not s:
        return []

    encoded_list = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            encoded_list.append((current_char, count))
            current_char = char
            count = 1

    encoded_list.append((current_char, count))
    return encoded_list

