def is_valid_parentheses(s: str) -> bool:
    stack = []
    matching_brackets = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching_brackets.values():
            stack.append(char)
        elif char in matching_brackets.keys():
            if not stack or stack.pop() != matching_brackets[char]:
                return False
        else:
            # Ignore any other characters
            continue

    return len(stack) == 0
