import math

def token_entropy(tokens: list[str]) -> float:
    if not tokens:
        return 0.0

    total_tokens = len(tokens)
    frequency_distribution = {}

    for token in tokens:
        if token in frequency_distribution:
            frequency_distribution[token] += 1
        else:
            frequency_distribution[token] = 1

    entropy = 0.0
    for count in frequency_distribution.values():
        probability = count / total_tokens
        if probability > 0:
            entropy -= probability * math.log2(probability)

    return round(entropy, 3)
