from typing import List

def longest_bitonic_length(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)

    # Initialize arrays to store the longest increasing subsequence ending at each index
    lis = [1] * n
    lds = [1] * n

    # Fill lis array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Fill lds array
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The length of the longest bitonic subsequence is the maximum value of lis[i] + lds[i] - 1
    return max(lis[i] + lds[i] - 1 for i in range(n))
