def min_max_normalize(nums: List[float]) -> List[float]:
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)

    if min_val == max_val:
        return [0.0] * len(nums)

    normalized_nums = [
        round((x - min_val) / (max_val - min_val), 2)
        for x in nums
    ]

    return normalized_nums
