import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match the expression
    pattern = r'^\s*(-?\d+(\.\d+)?)\s*(\+\s*(-?\d+(\.\d+)?)|\-\s*(-?\d+(\.\d+)?)|\*\s*(-?\d+(\.\d+)?)|\/\s*(-?\d+(\.\d+)?)|\*\*\s*(-?\d+(\.\d+)?)|\(\s*(-?\d+(\.\d+)?)\s*\))\s*$'

    if not re.match(pattern, expression):
        raise ValueError("Invalid expression format")

    def parse_expression(tokens):
        if len(tokens) == 1:
            return float(tokens[0])

        if tokens[1] == '+':
            return parse_expression(tokens[:2]) + parse_expression(tokens[2:])
        elif tokens[1] == '-':
            return parse_expression(tokens[:2]) - parse_expression(tokens[2:])
        elif tokens[1] == '*':
            return parse_expression(tokens[:2]) * parse_expression(tokens[2:])
        elif tokens[1] == '/':
            if parse_expression(tokens[2:]) == 0:
                raise ZeroDivisionError("Division by zero")
            return parse_expression(tokens[:2]) / parse_expression(tokens[2:])
        elif tokens[1] == '**':
            return parse_expression(tokens[:2]) ** parse_expression(tokens[2:])
        elif tokens[1] == '(':
            return parse_expression(tokens[2:-1])

    # Tokenize the expression
    tokens = re.findall(r'-?\d+(\.\d+)?|\+|-|\*|/|\*\*|\(|\)', expression)

    try:
        result = parse_expression(tokens)
    except ZeroDivisionError as e:
        raise ZeroDivisionError("Division by zero") from e

    return result
