def shortest_path_one_break(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def bfs(start_x, start_y):
        queue = [(start_x, start_y, 0, False)]  # (x, y, steps, has_broken)
        visited = set()

        while queue:
            x, y, steps, has_broken = queue.pop(0)

            if (x, y) == (rows - 1, cols - 1):
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if is_valid(nx, ny):
                    if (nx, ny, has_broken) not in visited:
                        visited.add((nx, ny, has_broken))
                        if grid[nx][ny] == 'E':
