from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize BFS queue and visited set
    queue = deque([(start, 0, False)])  # (position, steps, has_broken)
    visited = set([start])

    while queue:
        pos, steps, has_broken = queue.popleft()

        if pos == end:
            return steps

        for dx, dy in directions:
            nx, ny = pos[0] + dx, pos[1] + dy

            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#':
                    if not has_broken:
                        # Break the wall and continue
                        queue.append(((nx, ny), steps + 1, True))
                else:
                    # Move to the next cell
                    if (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append(((nx, ny), steps + 1, has_broken))

    return -1
