import re

def is_local_redirect(target: str, host: str) -> bool:
    # Check if target is a site-relative path
    if target.startswith('/') and not target[1:]:
        return True

    # Check if target is a full URL with the same host
    url_pattern = re.compile(r'^(https?://)?([a-zA-Z0-9.-]+)(:[0-9]+)?$')
    match = url_pattern.match(target)
    if match:
        url_host = match.group(2)
        if url_host.lower() == host.lower():
            return True

    # Check for invalid characters
    if any(ord(c) < 32 or ord(c) > 127 for c in target):
        return False

    return False

