def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Create an adjacency list representation of the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize a queue for BFS and a set to keep track of visited nodes
    queue = [(source, 0)]
    visited = {source}

    # Dictionary to store the shortest distance from source to each node
    shortest_distances = {source: 0}

    while queue:
        current_node, distance = queue.pop(0)

        # If we reach the target, return the number of paths
        if current_node == target:
            return 1

        # Explore neighbors
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))
                shortest_distances[neighbor] = distance + 1

    # If we finish the loop without finding the target, return 0
    return 0

