import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match the expression
    pattern = r'^\s*(-?\d+(\.\d+)?)\s*(\*\*|[-+*/])\s*(-?\d+(\.\d+)?)\s*$'

    # Check if the expression matches the pattern
    if not re.match(pattern, expression):
        raise ValueError("Invalid expression format")

    # Split the expression into components
    parts = expression.split()

    # Convert parts to floats
    try:
        num1 = float(parts[0])
        operator = parts[1]
        num2 = float(parts[2])
    except ValueError:
        raise ValueError("Invalid number in expression")

    # Evaluate the expression based on the operator
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            raise ZeroDivisionError("Division by zero")
        return num1 / num2
    elif operator == '**':
        return num1 ** num2
    else:
        raise ValueError("Unsupported operator")

