from typing import List

def stabilize_sandpile(grid: List[List[int]]) -> List[List[int]]:
    if not grid:
        return []

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0])

    def toppling(r, c):
        if grid[r][c] >= 4:
            grid[r][c] -= 4
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    grid[nr][nc] += 1

    while True:
        stable = True
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] >= 4:
                    stable = False
                    toppling(r, c)
        if stable:
            break

    return grid
