from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    # Initialize the board with all cells available
    board = [[True] * n for _ in range(n)]

    # Mark blocked cells
    for row, col in blocked:
        if 0 <= row < n and 0 <= col < n:
            board[row][col] = False

    def is_valid(row: int, col: int) -> bool:
        # Check if the current position is valid
        for i in range(n):
            if board[row][i] or board[i][col]:
                return False
        # Check diagonals
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j]:
                return False
        for i, j in zip(range(row, n), range(col, -1, -1)):
            if board[i][j]:
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_valid(row, col):
                board[row][col] = False
                count += backtrack(row + 1)
                board[row][col] = True
        return count

    return backtrack(0)
