import re

def expand_template(template: str, values: dict[str, str]) -> str:
    # Use a regular expression to find all occurrences of {{key}}
    matches = re.findall(r'{{(.*?)}}', template)

    # Replace each match with the corresponding value from the dictionary
    for match in matches:
        if match in values:
            template = template.replace(f"{{{match}}}", values[match])
        else:
            template = template.replace(f"{{{match}}}", f"{{{match}}}")  # Keep the placeholder if no value is found

