from typing import List

def shortest_path_one_break(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def bfs(start_x, start_y):
        queue = [(start_x, start_y, 0, False)]  # (x, y, steps, has_wall)
        visited = set()

        while queue:
            x, y, steps, has_wall = queue.pop(0)

            if (x, y) == (rows - 1, cols - 1):
                return steps

            if (x, y, has_wall) in visited:
                continue
            visited.add((x, y, has_wall))

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    if grid[nx][ny] == '#':
                        if not has_wall:
                            queue.append((nx, ny, steps + 1, True))
                    else:
                        queue.append((nx, ny, steps + 1, has_wall))

        return -1

    # Find starting positions
    start_x, start_y = None, None
    end_x, end_y = None, None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_x, start_y = i, j
            elif grid[i][j] == 'E':
                end_x, end_y = i, j

    # Perform BFS from both starting points
    return min(bfs(start_x, start_y), bfs(end_x, end_y))

