from typing import List

def subsets_with_sum(nums: List[int], k: int) -> List[List[int]]:
    def backtrack(start: int, path: List[int]):
        if sum(path) == k:
            result.append(path[:])
            return
        if sum(path) > k:
            return
        for i in range(start, len(nums)):
            path.append(nums[i])
            backtrack(i + 1, path)
            path.pop()

    result = []
    backtrack(0, [])
    return sorted(result)

