def is_local_redirect(target: str, host: str) -> bool:
    # Check if target is a site-relative path starting with a single slash
    if target.startswith('/') and '/' not in target[1:]:
        return True

    # Check if target is an absolute URL with a matching host
    url_pattern = re.compile(r'^(https?://)?([a-zA-Z0-9.-]+\.[a-zA-Z]{2,})(:[0-9]+)?$')
    match = url_pattern.match(target)
    if match:
        host_part = match.group(2)
        if host_part.lower() == host.lower():
            return True

    # Check for invalid characters
    if re.search(r'[\\ / \x00-\x1F]', target):
        return False

    return False

