import re

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Regular expression to match the URL pattern
    url_pattern = re.compile(
        r'^(https?://)?'  # Optional http or https scheme
        r'(?P<user>[^@]+)@'?  # Optional user info
        r'(?P<host>[^:/]+)'  # Host name
        r'(:[0-9]+)?$'  # Optional port
    )

    match = url_pattern.match(url)
    if not match:
        return False

    scheme = match.group('scheme') or 'http'
    user = match.group('user')
    host = match.group('host').lower().rstrip('.')

    if scheme not in ['http', 'https']:
        return False

    if user:
        return False

    if host not in allowed_hosts:
        return False

    # Check if the host matches any parent domain in allowed_hosts
    for allowed_host in allowed_hosts:
        if host.startswith(allowed_host + '.'):
            return False

    return True

