def evaluate_formula(formula: str, x: float) -> float:
    def parse_formula(formula):
        tokens = []
        i = 0
        while i < len(formula):
            if formula[i].isdigit() or formula[i] == '.':
                num = ''
                while i < len(formula) and (formula[i].isdigit() or formula[i] == '.'):
                    num += formula[i]
                    i += 1
                tokens.append(float(num))
            elif formula[i] in '+-*/**()':
                tokens.append(formula[i])
                i += 1
            elif formula[i] == 's' and formula[i:i+4] == 'sqrt':
                tokens.append('sqrt')
                i += 4
            elif formula[i] == 'a' and formula[i:i+3] == 'abs':
                tokens.append('abs')
                i += 3
            elif formula[i] == 's' and formula[i:i+3] == 'sin':
                tokens.append('sin')
                i += 3
            elif formula[i] == 'c' and formula[i:i+3] == 'cos':
                tokens.append('cos')
                i += 3
            else:
                raise ValueError("Invalid character in formula")
        return tokens

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '**':
            values.append(left ** right)
        elif operator == 'sqrt':
            values.append(math.sqrt(right))
        elif operator == 'abs':
            values.append(abs(right))
        elif operator == 'sin':
            values.append(math.sin(right))
        elif operator == 'cos':
            values.append(math.cos(right))

    def infix_to_postfix(tokens):
        operators = []
        postfix = []
        for token in tokens:
            if isinstance(token, float):
                postfix.append(token)
            elif token in '+-*/**()':
                while (operators and operators[-1] != '(' and
                       ((token == '*' or token == '/') and
                        (operators[-1] == '+' or operators[-1] == '-'))):
                    apply_operator(operators, postfix)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, postfix)
                operators.pop()
        while operators:
            apply_operator(operators, postfix)
        return postfix

    tokens = parse_formula(formula)
    postfix = infix_to_postfix(tokens)
    values = []
    for token in postfix:
        if isinstance(token, float):
            values.append(token)
        else:
            apply_operator(operators, values)
    return values[0]

