def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}

    for kind, item, quantity in events:
        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity
            while item in waiting and stock[item] >= waiting[item][1]:
                _, q = waiting.pop(item)
                stock[item] -= q
        elif kind == 'order':
            if item not in waiting:
                waiting[item] = []
            waiting[item].append((item, quantity))

    # Process waiting orders after all receive events
    for item in waiting:
        while waiting[item] and stock.get(item, 0) > 0:
            _, q = waiting[item].pop(0)
            if stock[item] >= q:
                stock[item] -= q
            else:
                waiting[item].insert(0, (item, q - stock[item]))
                break

    return stock, list(waiting.items())
