def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    rotated_matrix = [row[:] for row in matrix]

    for i in range(n // 2):
        start_row, end_row = i, n - i - 1
        start_col, end_col = i, n - i - 1

        # Extract the ring
        ring = []
        for j in range(start_row, end_row + 1):
            ring.append(matrix[j][start_col])
        for j in range(start_col + 1, end_col + 1):
            ring.append(matrix[end_row][j])
        for j in range(end_row - 1, start_row - 1, -1):
            ring.append(matrix[j][end_col])
        for j in range(end_col - 1, start_col, -1):
            ring.append(matrix[start_row][j])

        # Rotate the ring
        k = k % len(ring)
        if k > 0:
            ring = ring[-k:] + ring[:-k]

        # Place the rotated ring back into the matrix
        index = 0
        for j in range(start_row, end_row + 1):
            rotated_matrix[j][start_col] = ring[index]
            index += 1
        for j in range(start_col + 1, end_col + 1):
            rotated_matrix[end_row][j] = ring[index]
            index += 1
        for j in range(end_row - 1, start_row - 1, -1):
            rotated_matrix[j][end_col] = ring[index]
            index += 1
        for j in range(end_col - 1, start_col, -1):
            rotated_matrix[start_row][j] = ring[index]
            index += 1

    return rotated_matrix
