from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the positions of S and E
    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        return -1

    # Initialize the queue with the start position and steps
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, steps = queue.popleft()

        # If we reach the end, return the number of steps
        if current == end:
            return steps

        # Explore all possible moves
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc

            # Check if the new position is within bounds and not a wall
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                # If the new position has not been visited, add it to the queue
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), steps + 1))

    # If we exhaust the queue without reaching the end, return -1
    return -1
