def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    def is_valid(row: int, col: int) -> bool:
        # Check if the position is blocked
        for b_row, b_col in blocked:
            if b_row == row or b_col == col or abs(b_row - row) == abs(b_col - col):
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_valid(row, col):
                blocked.append((row, col))
                count += backtrack(row + 1)
                blocked.pop()
        return count

    return backtrack(0)
