import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_field(field):
        if field.startswith('"'):
            # Handle quoted field
            field = field[1:]
            while field:
                match = re.match(r'([^"]+)', field)
                if match:
                    yield match.group(1)
                    field = field[match.end():]
                else:
                    raise ValueError("Unmatched opening quote in quoted field")
                if field.startswith('"'):
                    field = field[1:]
                else:
                    break
            if not field.endswith(','):
                raise ValueError("Missing comma after quoted field")
            field = field[:-1]
        else:
            # Handle unquoted field
            field = field.split(',')
            for f in field:
                if '"' in f:
                    raise ValueError("Double quotes found in unquoted field")
            yield from field

    records = []
    current_record = []
    lines = text.split('\n')
    for line in lines:
        if line.strip():
            for field in parse_field(line):
                current_record.append(field)
            records.append(current_record)
            current_record = []
        elif current_record:
            records.append(current_record)
            current_record = []

    return records
