def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []
    keys = []

    for op, *args in operations:
        if op == "put":
            key, value = args
            if key in cache:
                del cache[key]
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op == "get":
            key, = args
            if key in cache:
                results.append(cache[key])
                keys.append(key)
                del cache[key]
                cache[key] = None  # Mark as recently used
            else:
                results.append(None)
                keys.append(None)

    return results, keys
