import re

def evaluate_expression(expr: str) -> int:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left / right))
        elif operator == '^':
            values.append(left ** right)

    def apply_unary_minus(values):
        values.append(-values.pop())

    def parse_expression(expr):
        expr = re.sub(r'\s+', '', expr)  # Remove spaces
        operators = []
        values = []
        i = 0
        while i < len(expr):
            if expr[i] in '0123456789':
                num = ''
                while i < len(expr) and expr[i].isdigit():
                    num += expr[i]
                    i += 1
                values.append(int(num))
            elif expr[i] == '(':
                operators.append(expr[i])
                i += 1
            elif expr[i] in '+-*/^':
                while (operators and operators[-1] in '^' and
                       (expr[i] in '+-' or expr[i] in '*/')):
                    apply_operator(operators, values)
                operators.append(expr[i])
                i += 1
            elif expr[i] == '-':
                if i == 0 or expr[i-1] in '()*/^+-':
                    apply_unary_minus(values)
                else:
                    i += 1
            elif expr[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Pop the '('
                i += 1
        while operators:
            apply_operator(operators, values)
        return values[0]

    return parse_expression(expr)

# Example usage:
