def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_columns = len(rows[0])
    if any(len(row) != num_columns for row in rows):
        raise ValueError("All rows must have the same number of columns")

    column_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    formatted_rows = []
    for row, alignment in zip(rows, aligns):
        formatted_cells = []
        for cell, width, align in zip(row, column_widths, alignment):
            padding = " " * (width - len(cell))
            if align == "l":
                formatted_cell = cell + padding
            elif align == "r":
                formatted_cell = padding + cell
            elif align == "c":
                half_padding = padding // 2
                formatted_cell = half_padding + cell + (padding - half_padding)
            else:
                raise ValueError(f"Invalid alignment character: {align}")
            formatted_cells.append(formatted_cell)
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
