import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Parse the expression using ast.literal_eval for simple expressions
    try:
        parsed_expr = ast.parse(expression, mode='eval').body
    except SyntaxError:
        raise ValueError("Invalid expression")

    def eval_expression(node):
        if isinstance(node, ast.Num):  # Integer or float
            return node.n
        elif isinstance(node, ast.Str):  # String literal
            return node.s
        elif isinstance(node, ast.Name):  # Variable name
            if node.id not in record:
                raise ValueError(f"Key '{node.id}' not found in record")
            return record[node.id]
        elif isinstance(node, ast.BinOp):  # Binary operation
            left = eval_expression(node.left)
            right = eval_expression(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            elif isinstance(node.op, ast.Lt):
                return left < right
            elif isinstance(node.op, ast.Le):
                return left <= right
            elif isinstance(node.op, ast.Gt):
                return left > right
            elif isinstance(node.op, ast.Ge):
                return left >= right
            elif isinstance(node.op, ast.Eq):
                return left == right
            elif isinstance(node.op, ast.NotEq):
                return left != right
        elif isinstance(node, ast.UnaryOp):  # Unary operation
            operand = eval_expression(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.Not):
                return not operand
        elif isinstance(node, ast.BoolOp):  # Boolean operation
            values = [eval_expression(child) for child in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            elif isinstance(node.op, ast.Or):
                return any(values)
        else:
            raise ValueError("Unsupported node type")

    try:
        return eval_expression(parsed_expr)
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")
