from typing import List

def teller_waits(arrivals: List[int], service_times: List[int], tellers: int) -> List[int]:
    if not arrivals or not service_times:
        return []

    wait_times = [0] * len(arrivals)
    teller_busy = [False] * tellers

    for i in range(len(arrivals)):
        # Find the first available teller
        for j in range(tellers):
            if not teller_busy[j]:
                teller_busy[j] = True
                wait_times[i] = arrivals[i]
                break

        # Calculate the end time of service
        end_time = wait_times[i] + service_times[i]

        # Update the busy status of the teller
        for k in range(tellers):
            if teller_busy[k] and teller_busy[k] < end_time:
                teller_busy[k] = end_time

    return wait_times
