    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        return "0"

    if number[0] == '-':
        negative = True
        number = number[1:]
    else:
        negative = False

    if not all(c.isalnum() and c.lower() in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number):
        raise ValueError("Invalid characters in number.")

    if number == '0':
        return "0"

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    num = 0

    for digit in number:
        num = num * from_base + digits.index(digit)

    if num == 0:
        return "0"

    result = ''
    while num > 0:
        result = digits[num % to_base] + result
        num //= to_base

    if negative:
        result = '-' + result

    return result
