import math

def evaluate_formula(formula: str, x: float) -> float:
    def parse_formula(formula: str) -> list:
        tokens = []
        i = 0
        while i < len(formula):
            if formula[i].isdigit() or formula[i] == '.':
                num = ''
                while i < len(formula) and (formula[i].isdigit() or formula[i] == '.'):
                    num += formula[i]
                    i += 1
                tokens.append(float(num))
            elif formula[i] in '+-*/**()':
                tokens.append(formula[i])
                i += 1
            elif formula[i] == ' ':
                i += 1
            else:
                raise ValueError(f"Invalid character '{formula[i]}' in formula")
        return tokens

    def apply_operator(operators: list, values: list) -> None:
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '**':
            values.append(left ** right)

    def apply_parentheses(tokens: list) -> None:
        stack = []
        for token in tokens:
            if token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1] != '(':
                    apply_operator(stack, values)
                stack.pop()
            else:
                values.append(token)

    def apply_functions(tokens: list) -> None:
        stack = []
        for token in tokens:
            if token in ['sqrt', 'abs', 'sin', 'cos']:
                stack.append(token)
            else:
                values.append(token)

    def apply_precedence(tokens: list) -> None:
        operators = []
        values = []
        apply_parentheses(tokens)
        apply_functions(tokens)
        for token in tokens:
            if token in ['+', '-', '*', '/', '**']:
                while (operators and operators[-1] in ['+', '-', '*', '/', '**'] and
                       ((operators[-1] == '*' or operators[-1] == '/') and
                        (token == '*' or token == '/')) or
                       ((operators[-1] == '+' or operators[-1] == '-') and
                        (token == '+' or token == '-'))):
                    apply_operator(operators, values)
                operators.append(token)
            else:
                values.append(token)
        while operators:
            apply_operator(operators, values)

    tokens = parse_formula(formula)
    apply_precedence(tokens)
    return values[0]

