from typing import List

def min_slides(grid: List[str]) -> int:
    def find_start_end(grid: List[str]) -> (int, int, int, int):
        for i, row in enumerate(grid):
            for j, char in enumerate(row):
                if char == 'S':
                    start_x, start_y = i, j
                elif char == 'E':
                    end_x, end_y = i, j
        return start_x, start_y, end_x, end_y

    def is_valid_move(x: int, y: int) -> bool:
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    def bfs(start_x: int, start_y: int, end_x: int, end_y: int) -> int:
        queue = [(start_x, start_y, 0)]
        visited = set()
        visited.add((start_x, start_y))

        while queue:
            x, y, steps = queue.pop(0)

            if (x, y) == (end_x, end_y):
                return steps

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if is_valid_move(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, steps + 1))

        return -1

    start_x, start_y, end_x, end_y = find_start_end(grid)
    if start_x == -1 or end_x == -1:
        return -1

    return bfs(start_x, start_y, end_x, end_y)
