from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []

    for op, key, value in operations:
        if op == "put":
            if key in cache:
                del cache[key]  # Remove existing key to make room
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove the least recently used item
            cache[key] = value  # Add the new key-value pair
        elif op == "get":
            if key in cache:
                results.append(cache[key])
                cache.move_to_end(key)  # Mark as most recently used
            else:
                results.append(None)

    # Convert OrderedDict to list of keys in order from least to most recently used
    keys = list(cache.keys())

    return results, keys
