def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for i, (op, *args) in enumerate(ops):
        if op == 'deposit':
            if args[1] not in balances:
                failed.append(i)
                continue
            if args[2] <= 0:
                failed.append(i)
                continue
            if balances[args[1]] < 0:
                failed.append(i)
                continue
            balances[args[1]] += args[2]
        elif op == 'withdraw':
            if args[1] not in balances:
                failed.append(i)
                continue
            if args[2] <= 0:
                failed.append(i)
                continue
            if balances[args[1]] < args[2]:
                failed.append(i)
                continue
            balances[args[1]] -= args[2]
        elif op == 'transfer':
            if args[1] not in balances or args[2] not in balances:
                failed.append(i)
                continue
            if args[1] == args[2]:
                failed.append(i)
                continue
            if balances[args[1]] < args[2] + 2:
                failed.append(i)
                continue
            balances[args[1]] -= args[2] + 2
            balances[args[2]] += args[2]
        elif op == 'freeze':
            if args[1] not in balances:
                failed.append(i)
                continue
            balances[args[1]] = -balances[args[1]]
        elif op == 'unfreeze':
            if args[1] not in balances:
                failed.append(i)
                continue
            balances[args[1]] = abs(balances[args[1]])
        else:
            failed.append(i)

    return final_balances, failed
