import re
from typing import Union

def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = re.sub(r'\s+', '', expr)

    def parse_factor() -> Union[int, float]:
        match = re.match(r'(\d+(\.\d+)?)', expr)
        if match:
            expr[:] = expr[match.end():]
            return float(match.group(0))

        if expr.startswith('('):
            expr[:] = expr[1:]
            result = evaluate_expression(expr)
            if not expr.startswith(')'):
                raise SyntaxError("Expected ')'")
            expr[:] = expr[1:]
            return result

        if expr.startswith('-'):
            expr[:] = expr[1:]
            return -parse_factor()

        raise SyntaxError("Unexpected token")

    def parse_term() -> Union[int, float]:
        result = parse_factor()
        while expr and expr[0] in ('*', '/'):
            op = expr[0]
            expr[:] = expr[1:]
            if op == '*':
                result *= parse_factor()
            elif op == '/':
                divisor = parse_factor()
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                result //= divisor
        return result

    def parse_expression() -> Union[int, float]:
        result = parse_term()
        while expr and expr[0] in ('+', '-'):
            op = expr[0]
            expr[:] = expr[1:]
            if op == '+':
                result += parse_term()
            elif op == '-':
                result -= parse_term()
        return result

    return int(parse_expression())
